// Abort BEFORE burning a partial episode — an episode renders every scene (💸).
// Mirrors MIN_TOKEN_BALANCE=2000 in show/MarketMayhem/show.env.
// Doubles as the config preflight, so an unfilled Show config fails here in
// seconds — not after the story step.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty — set it to a campaign id the API credential\'s account owns');
if (!cfg.userId) throw new Error('Show config: userId is empty — set it to the YakYak user id the API credential belongs to');
const user = $json;
if (user.tokenBalance === undefined) throw new Error('could not fetch the user record — check Show config userId and the "YakYak API" credential (' + (user.error?.message || 'no tokenBalance in response') + ')');
const balance = Number(user.tokenBalance || 0);
const min = Number(cfg.minTokenBalance || 2000);
if (balance < min) throw new Error('token balance ' + balance + ' is below the ' + min + ' minimum — top up before generating an episode');
return [{ json: { balance } }];

const TPL = "You are the head writer for "Market Mayhem", a daily dark-comedy short-form
video series that personifies the crypto/markets world. Real price action drives
the plot; the humor comes from the characters' voices and reaction shots. Your
job in this run is to produce ONE story.

STEP 1 — Read the data. The fetched market data is included below (Binance 24h
tickers for BTC/ETH/DOGE with a CoinGecko fallback, plus the alternative.me
Fear & Greed index). If a line is marked unavailable, note it and proceed with
what you have — never invent numbers. Gold and The Fed have no live feed in
this run: dramatize Gold qualitatively against the risk-on/risk-off mood, and
treat The Fed as the macro "interest-rate / disapproving parent" voice. Do NOT
give financial advice.

STEP 2 — Compute the read (in your reasoning):
  - The day's biggest GAINER and biggest LOSER among BTC / ETH / DOGE.
  - Overall mood: risk-on (green day) vs risk-off (red day).
  - The Fear & Greed classification — this is the emotional weather of the episode.
This computed read IS the plot. A green day and a red day must feel different.

STEP 3 — Write the story.

CAST (only these may speak; each scene's "leading character" must be one of them):
  - Max Mayhem — the manic Market Mayhem anchor. MUST be the leading character in
    Scene 1 (cold open, sets the day's mood) and Scene 8 (sign-off). Hyped,
    breathless, all-caps energy.
  - Bitcoin — the smug veteran who's seen every crash. Dry, been-here-before.
  - Ethereum — the earnest, over-explaining younger sibling. Tries too hard.
  - Doge — the chaos-gremlin Shiba Inu memecoin. Gleeful, unhinged, no impulse control.
  - The Fed — the disapproving parent of the whole market. Stern, deadpan, ominous.
  - Gold — the boomer bar of bullion. Slow, smug, "back in my day".

TONE: Dark comedy / market satire. Real price moves drive the beats; the comedy
comes from each character's voice and how they react to the day's numbers. No
financial advice, no real "buy/sell" calls, no slurs. Punch up, not down.

PER-SCENE REQUIREMENTS:
  - Roughly 200 words of prose describing the scene's visuals, action, and
    atmosphere (location, what we see, what the numbers just did, the reaction).
    Write it as a director would brief a camera op. Lean on the green/red color
    language and candlestick/ticker imagery.
  - Exactly ONE spoken dialog line per scene, 8–12 words, attributed to the
    scene's leading character. The line should land — a flex, a panic, a deadpan
    gut-punch. Do NOT end the dialog line with a period ("!" or "?" are fine).
  - Leading character must be from the cast. No other characters speak on the page.
  - The day's biggest mover should get the spotlight scene.

STRUCTURE: Exactly 8 scenes.
  - Scene 1: Max Mayhem cold-opens with the day's headline mood.
  - Scenes 2–7: the five assets react (Bitcoin, Ethereum, Doge, The Fed, Gold),
    with the day's biggest mover getting the strongest beat; you may give the
    spotlight asset a second scene instead of repeating a quiet one.
  - Scene 8: Max Mayhem signs off.

STEP 4 — Reply with ONLY the markdown document below — no preamble, no
triple-backtick fences, nothing after it:

  # Market Mayhem — Daily Close
  **Generated (UTC):** {{TS}}
  **Sources:** Binance 24h ticker (BTC/ETH/DOGE) + alternative.me Fear & Greed

  ## Social title: <punchy title for social posting, 50 characters MAX>

  ## Headlines we drew from:
  - <one bullet per real data point you used, e.g. "BTC +6.2% to $X (Binance 24h)">
  - <e.g. "Fear & Greed: Greed (71)">

  ## Scene 1 — <short title>
  **Leading character:** Max Mayhem
  **Dialog:** "<8–12 word line>"

  <~200 words of scene prose>

  ## Scene 2 — <short title>
  **Leading character:** <name from cast>
  **Dialog:** "<8–12 word line>"

  <~200 words of scene prose>

  ... (continue through Scene 8, which is again Max Mayhem) ...

===== MARKET DATA =====

{{DATA}}";

// The Market Mayhem head-writer prompt, adapted from show/MarketMayhem/prompt.md.
// Two changes vs the showrunner original: STEP 1's agentic WebFetch is replaced
// by the market data the fetch nodes just pulled (an API call can't fetch the
// web itself), and STEP 4's file-write becomes "reply with only the markdown".
// A '## Social title:' line is requested so ONE model call covers both the
// story and the ≤50-char social title.
const ts = new Date().toISOString();
const get = (node) => { try { return $(node).first().json || {}; } catch (e) { return {}; } };
const lines = [];
const bin = (label, node) => {
  const t = get(node);
  if (t.lastPrice === undefined) return false;
  lines.push(label + ': $' + Number(t.lastPrice) + ', 24h ' + Number(t.priceChangePercent).toFixed(2) + '%, high $' + Number(t.highPrice) + ' / low $' + Number(t.lowPrice) + ' (Binance 24h)');
  return true;
};
const gecko = get('Fetch CoinGecko');
const gk = (label, key) => {
  const g = gecko[key];
  if (!g || g.usd === undefined) return false;
  lines.push(label + ': $' + g.usd + ', 24h ' + Number(g.usd_24h_change || 0).toFixed(2) + '% (CoinGecko fallback)');
  return true;
};
const okBtc = bin('BTC', 'Fetch BTC') || gk('BTC', 'bitcoin');
const okEth = bin('ETH', 'Fetch ETH') || gk('ETH', 'ethereum');
const okDoge = bin('DOGE', 'Fetch DOGE') || gk('DOGE', 'dogecoin');
if (!okBtc && !okEth && !okDoge) throw new Error('no price data from Binance OR CoinGecko — aborting (no material for an episode)');
if (!okBtc) lines.push('BTC: (source unavailable this run — proceed without it)');
if (!okEth) lines.push('ETH: (source unavailable this run — proceed without it)');
if (!okDoge) lines.push('DOGE: (source unavailable this run — proceed without it)');
const f = get('Fetch Fear & Greed');
const fd = f.data && f.data[0] ? f.data[0] : null;
lines.push(fd ? 'Fear & Greed: ' + fd.value_classification + ' (' + fd.value + ')' : 'Fear & Greed: (source unavailable this run — proceed without it)');
const fill = (t, map) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (map[k] === undefined ? m : map[k]));
const prompt = fill(TPL, { TS: ts, DATA: lines.join('
') });
return [{ json: { prompt } }];

// Extract the story markdown from the Claude response, then port of
// storyToDescription() from show/showrunner/story-format.js: drop everything
// before the first '## Scene', collapse each scene's prose to one line, append
// `<Char> says: "<dialog>"`, mapping names through the cast map (CAST_ALIASES
// in show/MarketMayhem/show.env).
const resp = $json;
if (resp.stop_reason === 'refusal') throw new Error('Claude declined the request (stop_reason: refusal)');
const story = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n');
if (!/## Scene/.test(story)) throw new Error('Claude response contains no "## Scene" blocks — not a story');

// ≤50-char social title from the requested '## Social title:' line
let socialTitle = '';
const mTitle = story.match(/^##\s*Social title:\s*(.+)$/mi);
if (mTitle) socialTitle = [...mTitle[1].trim().replace(/^"|"$/g, '')].slice(0, 50).join('');

// caption from the headlines bullets
const capLines = [];
const hm = story.match(/## Headlines we drew from:\n([\s\S]*?)\n##/);
if (hm) for (const l of hm[1].split('\n')) { const t = l.replace(/^-\s*/, '').trim(); if (t) capLines.push(t); }
const socialCaption = capLines.slice(0, 6).join(' · ').slice(0, 400);

const ALIASES = {"Max Mayhem":"Max Mayhem","The Fed":"The Fed","Bitcoin":"Bitcoin","Ethereum":"Ethereum","Doge":"Doge","Gold":"Gold"};
const mapShort = (name) => { for (const k of Object.keys(ALIASES)) if (name.includes(k)) return ALIASES[k]; return String(name).trim(); };

const lines = story.split(/\r?\n/);
let inScene = false, n = 0, prose = '', character = '', dialog = '';
const parts = [];
const emit = () => {
  if (!inScene) return;
  const p = prose.replace(/[ \t]+/g, ' ').trim();
  const s = mapShort(character);
  parts.push(n === 0 ? '- ' + p + ' ' + s + ' says: "' + dialog + '"' : '\n\n  - ' + p + ' ' + s + ' says: "' + dialog + '"');
  n++;
};
for (const line of lines) {
  if (/^## Scene/.test(line)) { emit(); inScene = true; prose = ''; character = ''; dialog = ''; continue; }
  if (!inScene) continue;
  if (/^\*\*Leading character:\*\*/.test(line)) { character = line.replace(/^\*\*Leading character:\*\*[ \t]*/, ''); continue; }
  if (/^\*\*Dialog:\*\*/.test(line)) { dialog = line.replace(/^\*\*Dialog:\*\*[ \t]*/, '').trim().replace(/^"|"$/g, '').replace(/[.。]$/, ''); continue; }
  if (/^##/.test(line)) { emit(); inScene = false; continue; }
  prose += ' ' + line;
}
emit();
if (!parts.length) throw new Error('no scenes parsed from the story');
const plot = parts.join('');
return [{ json: { plot, socialTitle, socialCaption, scenes: n, story } }];

// Shape the engine call: episode mode in the pinned Market Mayhem campaign, the
// story as the new episode's plot, optional soundtrack pin. The engine's
// sub-workflow trigger is passthrough — this item IS the payload (same shape
// as the engine webhook's body). Re-delivered same-day stories are diff-aware
// on the engine side, so a duplicate run doesn't re-bill unchanged work.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty');
const movie = { plot: $json.plot };
if (cfg.soundtrackAudioPath) {
  movie.soundtrackAudioPath = cfg.soundtrackAudioPath;
  if (cfg.soundtrackVolume) movie.soundtrackVolume = Number(cfg.soundtrackVolume);
}
return [{ json: { target: { mode: 'episode', campaignId: cfg.campaignId }, changes: { movie }, chatWebhookUrl: '' } }];
